CREATE TABLE person (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(200) NOT NULL REFERENCES sheet (id),
    name       VARCHAR(200) NOT NULL,
    grade      VARCHAR(1)   NOT NULL,
    created_by VARCHAR(200) NOT NULL,
    created_at TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX person_sheet ON person (sheet_id, id);
-- A person's version: raised by every saved edit. An edit carries the version its form loaded and
-- is refused when someone else has saved the person since.
ALTER TABLE person ADD COLUMN version BIGINT NOT NULL DEFAULT 0;
-- The date a person is retired from (null: not retired). A person with the date set counts as
-- retired at once, whatever the date; their claims dated after it are refused.
ALTER TABLE person ADD COLUMN retired_from DA

