91	/** Takes a statement of the person: records their due-total now (the sum of the due of their claims that
92	 *  count live (OPEN ones of a person on hold do not), n/a ones skipped; n/a when their grade has no rate on the sheet's today and none of
93	 *  those claims keeps a settled or bound figure) on the sheet's today, and binds each counting claim
94	 *  to the figure under the due it shows now (its late charge is never bound); a claim that does not
95	 *  count live is unbound. */
96	public class TakeStatement {
97	    public void take(@Val Person person, PersonRepository people, ClaimRepository claims, RateRepository rates,
98	            SheetRepository sheets, SettingRepository settings) {
99	        String sheetId = person.getSheetId();
100	        LocalDate today = sheets.today(sheetId);
101	        String floor = settings.floor(sheetId);
102	        Dues.Late late = settings.late(sheetId, today);
103	        List<Claim> own = claims.listOf(sheetId, person.getId());
104	        BigDecimal total = BigDecimal.ZERO.setScale(2);
105	        boolean kept = false;
106	        int bound = 0;
107	        for (Claim c : own) {
108	            if (!person.countsLive(c)) {
109	                c.bind(false, null);
110	            } else {
111	                Rate rate = rates.find(sheetId, person.getGrade(), LocalDate.parse(c.getDate()));
112	                String live = rate == null ? null : Dues.of(c.getAmount(), rate.pct(), floor);
113	                String shown = Dues.shown(c, live, late);
114	                kept |= c.getSettledDue() != null || (c.isStated() && c.getStatedDue() != null);
115	                if (shown != null) total = total.add(new BigDecimal(shown));
116	                // The figure under it is bound; its late charge keeps following the sheet's today.
117	                c.bind(true, c.due(live));
118	                bound++;
119	            }
120	            claims.updateBinding(c);
121	        }
122	        boolean na = rates.find(sheetId, person.getGrade(), today) == null && !kept;
123	        person.stated(na ? null : total.toPlainString(), today.toString(), bound);
124	        people.updateStatements(person);
125	    }
126	}
