372	import org.springframework.jdbc.core.RowMapper;
373	import org.springframework.jdbc.support.GeneratedKeyHolder;
374	import org.springframework.stereotype.Repository;
375	
376	@Repository
377	public class PersonRepository {
378	
379	    private static final String COLUMNS = "id, sheet_id, name, grade, version, statement_count, stated_total, statement_date, retired_from, held";
380	
381	    private static final RowMapper<Person> ROW = (rs, n) -> {
382	        LocalDate stated = rs.getObject("statement_date", LocalDate.class);
383	        LocalDate retired = rs.getObject("retired_from", LocalDate.class);
384	        Person person = new Person(rs.getLong("id"), rs.getString("sheet_id"), rs.getString("name"),
385	                rs.getString("grade"), rs.getLong("version"), rs.getInt("statement_count"),
386	                rs.getString("stated_total"), stated == null ? null : stated.toString());
387	        person.setRetiredFrom(retired == null ? null : retired.toString());
388	        person.setHeld(rs.getBoolean("held"));
389	        return person;
390	    };
391	
392	    private final JdbcTemplate jdbc;
393	
394	    public PersonRepository(JdbcTemplate jdbc) {
395	        this.jdbc = jdbc;
396	    }
397	
398	    /** The sheet's people in the order they were added, each with their patrons. */
399	    public List<Person> list(String sheetId) {
400	        List<Person> people = jdbc.query("SELECT " + COLUMNS + " FROM person WHERE sheet_id = ? ORDER BY id",
401	                ROW, sheetId);
402	        Map<Long, Person> byId = new HashMap<>();
403	        people.forEach((p) -> byId.put(p.getId(), p));
404	        jdbc.query("SELECT person_id, patron_id FROM person_patron WHERE sheet_id = ? ORDER BY added_at, patron_id",
405	                (rs) -> {
406	                    Person p = byId.get(rs.getLong("person_id"));
407	                    if (p != null) {
408	                        p.getPatronIds().add(rs.getLong("patron_id"));
409	                    }
410	                }, sheetId);
411	        return people;
412	    }
413	
414	    public Person find(String sheetId, long id) {
415	        Person person = jdbc.query("SELECT " + COLUMNS + " FROM person WHERE sheet_id = ? AND id = ?",
416	                ROW, sheetId, id).stream().findFirst().orElse(null);
417	        if (person != null) {
418	            person.setPatronIds(new ArrayList<>(jdbc.queryForList(
419	                    "SELECT patron_id FROM person_patron WHERE sheet_id = ? AND person_id = ? ORDER BY added_at, patron_id",
420	                    Long.class, sheetId, id)));
421	        }
422	        return person;
423	    }
424	
425	    /** Name the patron as one of the person's patrons. */
426	    public void addPatron(Person person, Person patron, String user) {
427	        jdbc.update("INSERT INTO person_patron (sheet_id, person_id, patron_id, added_by) VALUES (?, ?, ?, ?)",
428	                person.getSheetId(), person.getId(), patron.getId(), user);
429	        person.getPatronIds().add(patron.getId());
430	    }
431	
432	    /** The person on the sheet with this name, compared ignoring case and surrounding spaces; null when none. */
433	    public Person findByName(String sheetId, String name) {
434	        return jdbc.query("SELECT " + COLUMNS + " FROM person WHERE sheet_id = ? AND name_key = LOWER(TRIM(?))",
435	                ROW, sheetId, name).stream().findFirst().orElse(null);
436	    }
437	
438	    /** Whether another person on the sheet already has this name, compared ignoring case and surrounding spaces. */
439	    public boolean nameTaken(String sheetId, String name, Long exceptId) {
440	        Integer n = jdbc.queryForObject(
441	                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND name_key = LOWER(TRIM(?)) AND (? IS NULL OR id <> ?)",
442	                Integer.class, sheetId, name, exceptId, exceptId);
443	        return n != null && n > 0;
444	    }
445	
446	    public Person add(String sheetId, String name, String grade, String user) {
447	        GeneratedKeyHolder key = new GeneratedKeyHolder();
448	        jdbc.update(con -> {
449	            PreparedStatement ps = con.prepareStatement(
450	                    "INSERT INTO person (sheet_id, name, grade, created_by) VALUES (?, ?, ?, ?)",
451	                    new String[] { "id" });
452	            ps.setString(1, sheetId);
453	            ps.setString(2, name);
454	            ps.setString(3, grade);
455	            ps.setString(4, user);
456	            return ps;
457	        }, key);
458	        return new Person(key.getKey().longValue(), sheetId, name, grade, 0);
459	    }
460	
461	    /** Save the person over the version it was loaded at, raising the version; false (nothing
462	     *  written) when someone else has saved the person since. */
463	    public boolean update(Person person) {
464	        int n = jdbc.update(
465	                "UPDATE person SET name = ?, grade = ?, version = version + 1 WHERE sheet_id = ? AND id = ? AND version = ?",
466	                person.getName(), person.getGrade(), person.getSheetId(), person.getId(), person.getVersion());
467	        if (n == 0) {
468	            return false;
469	        }
470	        person.setVersion(person.getVersion() + 1);
471	        return true;
472	    }
473	
474	    /** Save the person's statements (not an edit: the version stays). */
475	    public void updateStatements(Person person) {
476	        jdbc.update("UPDATE person SET statement_count = ?, stated_total = ?, statement_date = ? WHERE sheet_id = ? AND id = ?",
477	                person.getStatementCount(), person.getStatedTotal(), LocalDate.parse(person.getStatementDate()),
478	                person.getSheetId(), person.getId());
479	    }
480	
481	    /** Save the person's retirement date (not an edit: the version stays). */
482	    public void updateRetired(Person person) {
483	        jdbc.update("UPDATE person SET retired_from = ? WHERE sheet_id = ? AND id = ?",
484	                LocalDate.parse(person.getRetiredFrom()), person.getSheetId(), person.getId());
485	    }
486	
487	    /** Save whether the person is on hold (not an edit: the version stays). */
488	    public void updateHeld(Person person) {
489	        jdbc.update("UPDATE person SET held = ? WHERE sheet_id = ? AND id = ?",
490	                person.isHeld(), person.getSheetId(), person.getId());
491	    }
492	}
